if($billing['state']==='ready'||$billing['can_release']){ ?><?= form_open($url,['id'=>'fixed-billing-disable']); ?><input type="hidden" name="company_project_fixed_billing_csrf" value="<?= $esc($company_project_fixed_billing_csrf); ?>"><input type="hidden" name="request_key" value="<?= $esc($request_key); ?>"><input type="hidden" name="project_id" value="<?= (int)$project['id']; ?>"><input type="hidden" name="origin_id" value="<?= (int)$billing['origin_id']; ?>"><input type="hidden" name="action" value="disable"><button type="submit">Retirar declaração sem fatura</button><?= form_close(); ?><?php }}
if($project['status']==='completed'&&(!$billing||in_array($billing['state'],['ready','disabled'],true))){ ?><?= form_open($url,['id'=>'fixed-billing-prepare']); ?><input type="hidden" name="company_project_fixed_billing_csrf" value="<?= $esc($company_project_fixed_billing_csrf); ?>"><input type="hidden" name="request_key" value="<?= $esc($request_key); ?>"><input type="hidden" name="project_id" value="<?= (int)$project['id']; ?>"><input type="hidden" name="revision" value="<?= (int)$project['revision']; ?>"><input type="hidden" name="action" value="prepare"><label>Moeda<select id="fixed-billing-currency" name="billing[currency]"><?php foreach($currencies as $c){ ?><option value="<?= (int)$c['id']; ?>"><?= $esc($c['name']); ?></option><?php } ?></select></label><label>Data<input id="fixed-billing-date" type="date" name="billing[date]" value="<?= gmdate('Y-m-d'); ?>" required></label><label>Vencimento<input id="fixed-billing-due" type="date" name="billing[due_date]" value="<?= gmdate('Y-m-d'); ?>" required></label><label>Preço fixo do projeto, com ponto decimal<input id="fixed-billing-cost" name="billing[cost]" inputmode="decimal" required></label>
<fieldset><legend>Tributos sobre o preço fixo</legend><?php for($i=0;$i<10;$i++){ ?><label>Nome <?= $i+1; ?><input name="billing[taxes][<?= $i; ?>][name]" maxlength="100"></label><label>Alíquota %<input name="billing[taxes][<?= $i; ?>][rate]" value="0.00" inputmode="decimal"></label><?php } ?></fieldset><label>Desconto<select name="billing[discount_mode]"><option value="fixed">Valor fixo</option><option value="percent">Percentual</option></select></label><label>Valor do desconto<input name="billing[discount_value]" value="0.00" inputmode="decimal"></label><label>Aplicação<select name="billing[discount_type]"><option value="after_tax">Após tributos</option><option value="before_tax">Antes dos tributos</option></select></label><label>Ajuste com sinal e ponto decimal<input name="billing[adjustment]" value="0.00" inputmode="decimal"></label><label>Nota<textarea name="billing[note]" maxlength="2000"></textarea></label><label><input id="fixed-billing-confirm" type="checkbox" name="billable" value="1" required> Confirmo o preço fixo do projeto inteiro, sem duplicar tarefas já faturadas.</label><button id="fixed-billing-review" type="submit">Preservar declaração para revisão</button><?= form_close(); ?><?php }elseif($project['status']!=='completed'){ ?><p>Este perfil exige projeto concluído.</p><?php }} ?></section><?php require APPPATH.'views/admin/companies/layout_tail.php'; ?>
